package net.officefloor.hq.app.setting;

import net.officefloor.plugin.section.clazz.Parameter;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;

public class HandleInvalidSetting {
    public void handle(@Parameter InvalidSettingException ex, ObjectResponse<ResponseEntity<String>> response) {
        response.send(new ResponseEntity<>(ex.getMessage(), HttpStatus.BAD_REQUEST));
    }
}
package net.officefloor.hq.app.setting;

/** A setting that cannot be kept: an unknown key, or a value that key does not allow. */
public class InvalidSettingException extends Exception {
    public InvalidSettingException(String message) {
        super(message);
    }
}
package net.officefloor.hq.app.setting;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes SETTING_CHANGED to the audit file once the setting is stored (value= blank for none). Then writes the
 *  figures the change moved (see Rollup). */
public class RecordSettingChanged {
    public void record(@Val Setting setting, @Val SettingValues values, @Val RollupBefore before, Rollup rollup,
            Audit audit) {
        audit.record("SETTING_CHANGED sheet=" + setting.sheetId() + " by=" + values.by() + " key=" + setting.key()
                + " value=" + (setting.value() == null ? "" : setting.value()));
